use std::collections::{BTreeMap,BTreeSet};
use crate::expressions::Value;
pub fn points(domains: &[(String,Vec<Value>)]) -> Vec<BTreeMap<String,Value>> {
    fn visit(domains: &[(String,Vec<Value>)], index: usize, point: &mut BTreeMap<String,Value>, result: &mut Vec<BTreeMap<String,Value>>) {
        if index == domains.len() {
            result.push(point.clone());
            return;
        }
        for value in &domains[index].1 {
            point.insert(domains[index].0.clone(),value.clone());
            visit(domains,index+1,point,result);
        }
    }
    let mut result = Vec::new();
    visit(domains,0,&mut BTreeMap::new(),&mut result);
    result
}
pub fn days(days: &BTreeSet<usize>) -> String {
    let mut runs = Vec::new();
    let mut first = None;
    let mut last = 0;
    for &day in days {
        if first.is_none() {
            first = Some(day);
        } else if day != last+1 {
            runs.push(format!("{}-{}",first.unwrap(),last));
            first = Some(day);
        }
        last = day;
    }
    if let Some(first) = first {
        runs.push(format!("{}-{}",first,last));
    }
    runs.join(",")
}
pub fn winner(algorithm: &str, first: usize, second: usize, first_effect: usize) -> usize {
    match algorithm {
        "first-applicable" => first,"deny-overrides" | "permit-unless-deny" => if first_effect == 1 {
            first
        } else {
            second
        },_ => if first_effect == 0 {
            first
        } else {
            second
        }
    }
}
pub fn blocker(earlier: &[usize], standalone: &[usize]) -> Option<usize> {
    earlier.iter().copied().find(|&rule| standalone[rule] != 2)
}

pub const NAMES: [&str;6] = ["PERMIT","DENY","NOT_APPLICABLE","INDETERMINATE{D}","INDETERMINATE{P}","INDETERMINATE{DP}"];
#[derive(Clone)] pub struct Decision {
    pub kind: usize,
    pub reason: String
}
impl Decision {
    pub fn new(kind: usize) -> Self {
        Self {
            kind,
            reason: String::new()
        }
    }
    pub fn notation(&self) -> String {
        if self.kind < 3 {
            NAMES[self.kind].to_owned()
        } else {
            format!("{} ({})",NAMES[self.kind],self.reason)
        }
    }
}
#[derive(Clone)] pub struct Target {
    pub kind: usize,
    pub reason: String
}
impl Target {
    pub fn name(&self) -> &str {
        ["MATCH","NO_MATCH","INDETERMINATE"][self.kind]
    }
}
pub trait Evaluator {
    fn evaluate(&mut self, element: usize) -> Decision;
    fn check(&mut self, element: usize) -> Target;
    fn id(&self, element: usize) -> &str;
}
pub struct Combined {
    pub decision: Decision,
    pub evaluated: Vec<usize>
}
pub fn run(evaluator: &mut impl Evaluator, algorithm: &str, children: &[usize]) -> Combined {
    if algorithm == "only-one-applicable" {
        let mut matched = None;
        for &child in children {
            let target = evaluator.check(child);
            if target.kind == 2 {
                return Combined {
                    decision: Decision {
                        kind: 5,
                        reason: target.reason
                    },
                    evaluated: Vec::new()
                };
            }
            if target.kind == 0 {
                if let Some(first) = matched {
                    return Combined {
                        decision: Decision {
                            kind: 5,
                            reason: format!("multiple applicable {} {}",evaluator.id(first),evaluator.id(child))
                        },
                        evaluated: Vec::new()
                    };
                }
                matched = Some(child);
            }
        }
        return if let Some(child) = matched {
            Combined {
                decision: evaluator.evaluate(child),
                evaluated: vec![child]
            }
        } else {
            Combined {
                decision: Decision::new(2),
                evaluated: Vec::new()
            }
        };
    }
    let mut decisions = Vec::new();
    let mut evaluated = Vec::new();
    for &child in children {
        let decision = evaluator.evaluate(child);
        evaluated.push(child);
        let stop = match algorithm {
            "deny-overrides" | "permit-unless-deny" => decision.kind == 1,"permit-overrides" | "deny-unless-permit" => decision.kind == 0,"first-applicable" => decision.kind != 2,_ => false
        };
        if stop {
            return Combined {
                decision,
                evaluated
            };
        }
        decisions.push(decision);
    }
    let has = |kind| decisions.iter().any(|d| d.kind == kind);
    let kind = match algorithm {
        "deny-overrides" => if has(5) || (has(3) && (has(4) || has(0))) {
            5
        } else if has(3) {
            3
        } else if has(0) {
            0
        } else if has(4) {
            4
        } else {
            2
        }, "permit-overrides" => if has(5) || (has(4) && (has(3) || has(1))) {
            5
        } else if has(4) {
            4
        } else if has(1) {
            1
        } else if has(3) {
            3
        } else {
            2
        }, "deny-unless-permit" => 1,"permit-unless-deny" => 0,_ => 2
    };
    let reason = if kind >= 3 {
        decisions.iter().find(|d| d.kind >= 3).unwrap().reason.clone()
    } else {
        String::new()
    };
    Combined {
        decision: Decision {
            kind,
            reason
        },
        evaluated
    }
}

#[derive(Clone,PartialEq,Eq)] pub enum Value {
    Integer(i64),
    String(String),
    Boolean(bool),
    Bag(Vec<String>)
}
impl Value {
    pub fn notation(&self) -> String {
        match self {
            Self::Integer(v) => v.to_string(),Self::String(v) => format!("\"{}\"",v),Self::Boolean(v) => v.to_string(),Self::Bag(v) => format!("[{}]",v.iter().map(|s| format!("\"{}\"",s)).collect::<Vec<_>>().join(","))
        }
    }
}
#[derive(Clone)] pub enum Expr {
    Literal(Value),
    Attribute(String),
    It,
    Unary(String,Box<Expr>),
    Binary(String,Box<Expr>,Box<Expr>),
    Call(String,Vec<Expr>)
}
struct Parser {
    tokens: Vec<String>,
    at: usize
}
fn tokens(source: &str) -> Vec<String> {
    let bytes = source.as_bytes();
    let mut at = 0;
    let mut tokens = Vec::new();
    while at < bytes.len() {
        if bytes[at] == b' ' {
            at += 1;
            continue;
        }
        let first = at;
        if bytes[at] == b'"' {
            at += 1;
            while bytes[at] != b'"' {
                at += 1;
            }
            at += 1;
        } else if bytes[at].is_ascii_alphanumeric() {
            at += 1;
            while at < bytes.len() && (bytes[at].is_ascii_alphanumeric() || b"_.".contains(&bytes[at])) {
                at += 1;
            }
        } else {
            at += 1;
            if at < bytes.len() && bytes[at] == b'=' && b"=!<>".contains(&bytes[first]) {
                at += 1;
            }
        }
        tokens.push(source[first..at].to_owned());
    }
    tokens
}
impl Parser {
    fn peek(&self) -> &str {
        self.tokens.get(self.at).map_or("",String::as_str)
    }
    fn take(&mut self) -> String {
        let token = self.tokens[self.at].clone();
        self.at += 1;
        token
    }
    fn expression(&mut self, minimum: usize) -> Expr {
        let first = self.take();
        let mut left = if first == "not" || first == "-" {
            let binding = if first == "not" {
                3
            } else {
                7
            };
            Expr::Unary(first,Box::new(self.expression(binding)))
        } else if first == "(" {
            let expression = self.expression(1);
            self.take();
            expression
        } else if first == "[" {
            let mut values = Vec::new();
            if self.peek() != "]" {
                loop {
                    let value = self.take();
                    values.push(value[1..value.len()-1].to_owned());
                    if self.peek() != "," {
                        break;
                    }
                    self.take();
                }
            }
            self.take();
            Expr::Literal(Value::Bag(values))
        } else if first.starts_with('"') {
            Expr::Literal(Value::String(first[1..first.len()-1].to_owned()))
        } else if first.bytes().all(|b| b.is_ascii_digit()) {
            Expr::Literal(Value::Integer(first.parse().unwrap()))
        } else if first == "true" || first == "false" {
            Expr::Literal(Value::Boolean(first == "true"))
        } else if first == "it" {
            Expr::It
        } else if self.peek() == "(" {
            self.take();
            let mut arguments = Vec::new();
            if self.peek() != ")" {
                loop {
                    arguments.push(self.expression(1));
                    if self.peek() != "," {
                        break;
                    }
                    self.take();
                }
            }
            self.take();
            Expr::Call(first,arguments)
        } else {
            Expr::Attribute(first)
        };
        loop {
            let binding = match self.peek() {
                "or" => 1,"and" => 2,"==" | "!=" | "<" | "<=" | ">" | ">=" | "in" => 4,"+" | "-" => 5,"*" => 6,_ => 0
            };
            if binding < minimum {
                break;
            }
            let operator = self.take();
            let right = self.expression(binding+1);
            left = Expr::Binary(operator,Box::new(left),Box::new(right));
        }
        left
    }
}
pub fn parse(source: &str) -> Expr {
    Parser {
        tokens: tokens(source),
        at: 0
    }.expression(1)
}

